function fc(i){const d=i.value.replace(/\D/g,'').slice(0,16);i.value=d.replace(/(\d{4})(?=\d)/g,'$1 ');const b=d[0]=='4'?'Visa':d[0]=='5'?'Mastercard':d[0]=='2'?'Мир':'',m=$('#cb');m.style.color='';
if(d.length==16){const ok=luhn(d);m.style.color=ok?'var(--ok)':'var(--er)';m.textContent=(b?b+' · ':'')+(ok?T('Номер корректный ✓','Number is valid ✓'):T('Такого номера не существует, проверьте цифры','This number is invalid, check the digits'))}else m.textContent=b}
async function addReq(){const a=val('r1'),r={t:rt,a};
if(rt=='stars'){if(!/^@?[A-Za-z][A-Za-z0-9_]{4,31}$/.test(a))return toast(T('Юзернейм: от 5 символов, латиница, цифры и _','Username: 5+ chars, letters, digits, _'));r.a='@'+a.replace('@','')}
else if(rt=='crypto'){r.b=nw;r.c=val('r3');if(a.length<2)return toast(T('Укажите название кошелька','Enter the wallet name'));if(!NH[nw][1].test(r.c))return toast(T('Адрес не похож на кошелёк сети ','This is not a valid address for ')+nw)}
else{r.cc=cc;if(cc=='RU'&&cm=='sbp'){let p=a.replace(/\D/g,'');if(p.length==11&&p[0]=='8')p='7'+p.slice(1);if(p.length==10&&p[0]=='9')p='7'+p;if(!/^79\d{9}$/.test(p))return toast(T('Телефон: +7 9XX XXX-XX-XX','Phone: +7 9XX XXX-XX-XX'));r.sbp=1;r.a=p;r.b=val('r2');if(r.b.length<2)return toast(T('Укажите банк','Enter the bank'))}else{r.a=a.replace(/\s/g,'');if(!/^\d{16}$/.test(r.a)||!luhn(r.a))return toast(T('Проверьте номер карты','Check the card number'))}}
if(await api('req.add',{r})){toast(T('Реквизиты привязаны','Details linked'));if(ret){const g=ret;ret='';location.hash=g;return}reqPage()}}
