function sqImg(src,sx,sy,sw,Z){let cur=src,x0=sx,y0=sy,s=sw;
while(s/2>=Z){const n=Math.round(s/2),c=document.createElement('canvas');c.width=c.height=n;const g=c.getContext('2d');g.imageSmoothingEnabled=true;g.imageSmoothingQuality='high';g.drawImage(cur,x0,y0,s,s,0,0,n,n);cur=c;x0=y0=0;s=n}
Z=Math.min(Z,s);const c=document.createElement('canvas');c.width=c.height=Z;const g=c.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,Z,Z);g.imageSmoothingEnabled=true;g.imageSmoothingQuality='high';g.drawImage(cur,x0,y0,s,s,0,0,Z,Z);return c}
async function setAv(i){const f=i.files[0];i.value='';if(!f)return;let src;
try{src=await createImageBitmap(f,{imageOrientation:'from-image'})}catch(e){try{src=await new Promise((ok,no)=>{const im=new Image();im.onload=()=>ok(im);im.onerror=no;im.src=URL.createObjectURL(f)})}catch(e2){return toast(T('Не удалось открыть фото','Could not open the photo'))}}
const w=src.width||src.naturalWidth,h=src.height||src.naturalHeight,m=Math.min(w,h),c=sqImg(src,(w-m)/2,(h-m)/2,m,720);
let img=c.toDataURL('image/jpeg',.93);if(img.length>900000)img=c.toDataURL('image/jpeg',.8);
if(await api('avatar',{img}))go()}

